package oidc

import (
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// Trust files come from users and may be generated by anything. These fuzz
// targets check that the parsers never panic and that what they return keeps
// its invariants: a known provider, a target, valid pattern ops, and a warning
// for every condition not understood. `go test` runs only the seed corpus.

func fixtureSeeds(t testing.TB) [][]byte {
	var out [][]byte
	err := filepath.WalkDir("testdata", func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() || filepath.Ext(path) != ".json" {
			return err
		}
		b, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		out = append(out, b)
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return out
}

func FuzzParseFile(f *testing.F) {
	for _, s := range fixtureSeeds(f) {
		f.Add(s)
	}
	const fed = `"Principal":{"Federated":"arn:aws:iam::111111111111:oidc-provider/token.actions.githubusercontent.com"},"Action":"sts:AssumeRoleWithWebIdentity"`
	for _, s := range []string{
		``, `{`, `null`, `[]`, `[null]`, `{}`, `"x"`, `{"Statement":null}`, `{"Statement":[]}`, `{"Statement":[1]}`,
		`{"Statement":{"Effect":"Allow",` + fed + `}}`,
		`{"Statement":[{"Effect":"Allow",` + fed + `,"Condition":{"StringLike":{"token.actions.githubusercontent.com:sub":["repo:*",1,true,null,{"a":1}]}}}]}`,
		`{"Statement":[{"Effect":"Allow",` + fed + `,"Condition":{"ForAllValues:StringNotLikeIfExists":{"token.actions.githubusercontent.com:":"x"},"x":1}}]}`,
		`{"Role":{"AssumeRolePolicyDocument":"%7B%22Statement%22%3A%5B%5D%7D"}}`,
		`{"Roles":[{"AssumeRolePolicyDocument":{"Statement":[]}},1]}`,
		`{"name":"projects/1/locations/global/workloadIdentityPools/p/providers/q","oidc":{"issuerUri":"https://token.actions.githubusercontent.com"},"attributeCondition":"assertion.a == 'b' || !assertion.c.startsWith('d') && (assertion.e in ['f', 'g'])"}`,
		`{"name":"x","oidc":{"issuerUri":"https://token.actions.githubusercontent.com"},"attributeCondition":"((((("}`,
		`{"oidc":{"issuerUri":"https://token.actions.githubusercontent.com"},"attributeMapping":{"google.subject":1},"attributeCondition":7}`,
		`{"bindings":[{"role":"roles/iam.workloadIdentityUser","members":["principalSet://iam.googleapis.com/projects/1/locations/global/workloadIdentityPools/p/attribute.x/y","principal://x/workloadIdentityPools/","principalSet:///workloadIdentityPools/p/attribute."]}]}`,
		`[{"issuer":"https://token.actions.githubusercontent.com","claimsMatchingExpression":{"value":"claims['sub'] matches 'repo:*' or claims[''] eq 'x' and (claims['a'] eq"}}]`,
		`[{"issuer":"https://token.actions.githubusercontent.com","subject":"repo:acme-app/web:pull_request","id":"/x/FEDERATEDIDENTITYCREDENTIALS/","audiences":[]}]`,
		`[{"issuer":"https://token.actions.githubusercontent.com","subject":"s","id":"İİ/federatedIdentityCredentials/x"}]`,
		`{"value":[{"issuer":"https://ghes.acme.example/_services/token","subject":"s"}],"appId":"a"}`,
		"\xef\xbb\xbf{\"Statement\":[]}",
		strings.Repeat("[", 5000) + strings.Repeat("]", 5000),
	} {
		f.Add([]byte(s))
	}
	f.Fuzz(func(t *testing.T, data []byte) {
		r, err := ParseBytes("fuzz.json", data, Options{})
		if err != nil {
			if !errors.Is(err, ErrUnknownFormat) {
				t.Fatalf("error does not wrap ErrUnknownFormat: %v", err)
			}
			return
		}
		for _, tr := range r.Trusts {
			checkTrust(t, tr)
		}
	})
}

func FuzzParseCEL(f *testing.F) {
	for _, s := range []string{
		"assertion.sub == 'repo:acme-app/web:ref:refs/heads/main'",
		"assertion.repository_owner == 'acme-app' && assertion.ref.startsWith('refs/heads/')",
		"attribute.repo in ['acme-app/web', \"acme-app/api\"] || !(assertion.ref == 'x')",
		"'acme-app' == assertion.repository_owner && size(assertion.x) > 0",
		"assertion.workflow_ref.matches('^acme-app/') && (assertion.a == 'b' || (assertion.c == 'd' && assertion.e == 'f'))",
		"(((assertion.a == 'b')))", "((", "))", "'unterminated", `"\"`, "a.b.c.d(", "!", "&& ||", "",
		strings.Repeat("!", 100) + "assertion.a == 'b'",
	} {
		f.Add(s)
	}
	p := &gcpProvider{mapping: map[string]string{"google.subject": "assertion.sub", "attribute.repo": "assertion.repository"}}
	f.Fuzz(func(t *testing.T, expr string) {
		checkExpr(t, parseExpr(expr, celDialect, p.resolver()))
	})
}

func FuzzParseAzureExpression(f *testing.F) {
	for _, s := range []string{
		"claims['sub'] matches 'repo:acme-app/web:ref:refs/heads/*'",
		"claims['sub'] eq 'repo:acme-app/web:environment:prod' or claims['sub'] eq 'repo:acme-app/api:environment:prod'",
		"(claims['ref'] eq 'refs/heads/main') AND claims[\"repository_owner\"] eq 'acme-app'",
		"claims['sub'].startsWith('repo:acme')", "claims[", "claims['']", "or", "(", "",
	} {
		f.Add(s)
	}
	f.Fuzz(func(t *testing.T, expr string) {
		checkExpr(t, parseExpr(expr, azureDialect, azureResolve))
	})
}

func checkExpr(t *testing.T, dnf [][]leaf) {
	t.Helper()
	if len(dnf) == 0 || len(dnf) > maxDNF {
		t.Fatalf("%d conjunctions", len(dnf))
	}
	for _, conj := range dnf {
		if len(conj) == 0 {
			t.Fatal("empty conjunction would mean match all")
		}
		tr := Trust{Provider: GCP, Target: "x", File: "x", Issuer: "https://token.actions.githubusercontent.com"}
		tr.applyConj(conj)
		checkTrust(t, tr)
		for _, l := range conj {
			if len(l.pats) == 0 {
				t.Fatalf("leaf without patterns: %+v", l)
			}
		}
	}
}

func TestFuzzSeedsParse(t *testing.T) {
	if n := len(fixtureSeeds(t)); n < 12 {
		t.Fatalf("only %d fixture seeds", n)
	}
}
